USE db_inventarios;
CREATE TABLE IF NOT EXISTS warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
INSERT IGNORE INTO warehouses (id,name) VALUES (1,'Almacén principal');
CREATE TABLE IF NOT EXISTS batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL DEFAULT 1, lot_number VARCHAR(100) NOT NULL, expiry_date DATE NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 0, reserved INT UNSIGNED NOT NULL DEFAULT 0, unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_batch (product_id,warehouse_id,lot_number), INDEX ix_product_expiry (product_id,expiry_date), FOREIGN KEY (warehouse_id) REFERENCES warehouses(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, batch_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, movement_type VARCHAR(30) NOT NULL, quantity INT UNSIGNED NOT NULL, reference_key VARCHAR(150) UNIQUE, actor_user_id BIGINT UNSIGNED, occurred_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference_key VARCHAR(150) NOT NULL UNIQUE, status ENUM('active','confirmed','released') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservation_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT UNSIGNED NOT NULL, batch_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, FOREIGN KEY (reservation_id) REFERENCES reservations(id), FOREIGN KEY (batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
